"""Check a library volunteer rota in CSV format."""

import argparse
import csv
import re
import sys
from collections import defaultdict
from dataclasses import dataclass
from datetime import date

COLUMNS = ("volunteer", "date", "start", "end", "assignment")


@dataclass
class Shift:
    line: int
    volunteer: str
    date: str
    start: str
    end: str
    assignment: str

    def label(self):
        return f"line {self.line} ({self.assignment}, {self.start}–{self.end})"


def validate(shift):
    errors = []
    if not shift.volunteer:
        errors.append("volunteer is empty")
    if not shift.assignment:
        errors.append("assignment is empty")
    try:
        if not re.fullmatch(r"[0-9]{4}-[0-9]{2}-[0-9]{2}", shift.date):
            raise ValueError
        date.fromisoformat(shift.date)
    except ValueError:
        errors.append(f"date {shift.date!r} must be a real date in YYYY-MM-DD format")

    valid_times = True
    for field in ("start", "end"):
        value = getattr(shift, field)
        if not re.fullmatch(r"(?:[01][0-9]|2[0-3]):[0-5][0-9]", value):
            errors.append(f"{field} {value!r} must use 24-hour HH:MM (00:00–23:59)")
            valid_times = False
    if valid_times and shift.start >= shift.end:
        errors.append(f"end {shift.end} must be later than start {shift.start} on the same date")
    return errors


def check(stream):
    reader = csv.reader(stream, strict=True)
    header = next(reader, [])
    fields = [field.strip() for field in header]
    if sorted(fields) != sorted(COLUMNS):
        raise ValueError("expected each of these column headers once: " + ", ".join(COLUMNS))

    groups = defaultdict(list)
    issues = []
    count = 0
    while True:
        line = reader.line_num + 1
        try:
            row = next(reader)
        except StopIteration:
            break
        except csv.Error as error:
            raise ValueError(f"CSV record starting at line {line}: {error}") from error
        if not row:
            continue
        count += 1
        if len(row) != len(fields):
            issues.append(f"Line {line}: expected {len(fields)} fields, found {len(row)}")
            continue
        shift = Shift(line=line, **dict(zip(fields, (cell.strip() for cell in row))))
        errors = validate(shift)
        if errors:
            issues.append(f"Line {line}: " + "; ".join(errors))
            continue
        name_key = " ".join(shift.volunteer.casefold().split())
        groups[name_key, shift.date].append(shift)

    for shifts in groups.values():
        active = []
        for shift in sorted(shifts, key=lambda item: (item.start, item.line)):
            active = [other for other in active if other.end > shift.start]
            for other in active:
                issues.append(f"Overlap for {shift.volunteer} on {shift.date}: "
                              f"{other.label()} and {shift.label()}")
            active.append(shift)
    return count, issues


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("rota", help="path to a UTF-8 CSV rota")
    args = parser.parse_args()
    try:
        with open(args.rota, encoding="utf-8-sig", newline="") as stream:
            count, issues = check(stream)
    except (OSError, ValueError, csv.Error) as error:
        print(f"Cannot check {args.rota}: {error}", file=sys.stderr)
        return 2
    for issue in issues:
        print(issue)
    print(f"Assignment rows: {count}. Issues: {len(issues)}.")
    return int(bool(issues))


if __name__ == "__main__":
    sys.exit(main())

#!/usr/bin/env python3
"""Check a library volunteer rota exported as CSV."""

import argparse
import csv
import re
import sys
from dataclasses import dataclass
from datetime import date
from itertools import groupby


HEADER = ["volunteer", "date", "start", "end", "assignment"]
DATE_FORMAT = re.compile(r"[0-9]{4}-[0-9]{2}-[0-9]{2}")
TIME_FORMAT = re.compile(r"[0-9]{2}:[0-9]{2}")


@dataclass(frozen=True)
class Shift:
    line: int
    volunteer: str
    day: date
    start: int
    end: int
    assignment: str


def parse_date(value):
    if DATE_FORMAT.fullmatch(value):
        return date.fromisoformat(value)
    raise ValueError("expected YYYY-MM-DD")


def parse_time(value, *, is_end=False):
    if not TIME_FORMAT.fullmatch(value):
        raise ValueError("expected 24-hour HH:MM, such as 09:30")
    hours, minutes = map(int, value.split(":"))
    if is_end and (hours, minutes) == (24, 0):
        return 24 * 60
    if minutes >= 60:
        raise ValueError("minutes must be 00–59")
    if hours >= 24:
        allowed = "hours must be 00–23, or use 24:00 for midnight" if is_end else "hours must be 00–23"
        raise ValueError(allowed)
    return hours * 60 + minutes


def parse_row(row, line, errors):
    if len(row) != len(HEADER):
        errors.append(f"Line {line}: expected {len(HEADER)} fields, found {len(row)}")
        return None

    volunteer, day_text, start_text, end_text, assignment = map(str.strip, row)
    previous_error_count = len(errors)
    for field, value in (("volunteer", volunteer), ("assignment", assignment)):
        if not value:
            errors.append(f"Line {line}: {field} is required")

    parsed = {}
    for field, value, parse in (
        ("date", day_text, parse_date),
        ("start", start_text, parse_time),
        ("end", end_text, lambda value: parse_time(value, is_end=True)),
    ):
        try:
            parsed[field] = parse(value)
        except ValueError as error:
            errors.append(f"Line {line}: invalid {field} {value!r} ({error})")

    if previous_error_count != len(errors):
        return None
    if parsed["end"] <= parsed["start"]:
        errors.append(
            f"Line {line}: end {end_text} must be later than start {start_text}. "
            "Split overnight shifts at midnight."
        )
        return None
    return Shift(line, volunteer, parsed["date"], parsed["start"], parsed["end"], assignment)


def read_rota(source):
    reader = csv.reader(source, strict=True)
    shifts = []
    errors = []
    line = 1
    try:
        if next(reader, None) != HEADER:
            return shifts, [f"Line 1: expected CSV header {','.join(HEADER)}"]
        while True:
            line = reader.line_num + 1
            row = next(reader, None)
            if row is None:
                break
            if not row or (len(row) == 1 and not row[0].strip()):
                continue
            shift = parse_row(row, line, errors)
            if shift is not None:
                shifts.append(shift)
    except csv.Error as error:
        errors.append(f"Line {line}: malformed CSV ({error})")
    return shifts, errors


def volunteer_day(shift):
    return shift.volunteer.casefold(), shift.day


def find_overlaps(shifts):
    ordered = sorted(shifts, key=lambda shift: (*volunteer_day(shift), shift.start, shift.line))
    for _, group in groupby(ordered, key=volunteer_day):
        same_day = list(group)
        for index, first in enumerate(same_day):
            for later_index in range(index + 1, len(same_day)):
                second = same_day[later_index]
                if second.start >= first.end:
                    break
                yield first, second


def format_time(minutes):
    hours, minutes = divmod(minutes, 60)
    return f"{hours:02}:{minutes:02}"


def describe(shift):
    return (
        f"line {shift.line} {shift.assignment!r} "
        f"({format_time(shift.start)}–{format_time(shift.end)})"
    )


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("csv_file", help="path to a UTF-8 rota CSV file")
    args = parser.parse_args()

    try:
        with open(args.csv_file, encoding="utf-8-sig", newline="") as source:
            shifts, errors = read_rota(source)
    except UnicodeDecodeError:
        print(f"Could not read {args.csv_file!r}. Export the rota as UTF-8 CSV.", file=sys.stderr)
        return 2
    except OSError as error:
        print(f"Could not read {args.csv_file!r} ({error.strerror})", file=sys.stderr)
        return 2

    for error in errors:
        print(error)

    conflict_count = 0
    for first, second in find_overlaps(shifts):
        print(f"Overlap for {first.volunteer!r} on {first.day}: {describe(first)} and {describe(second)}")
        conflict_count += 1

    print(f"Valid assignments checked: {len(shifts)} | Overlapping pairs: {conflict_count}")
    if errors:
        return 2
    return int(conflict_count > 0)


if __name__ == "__main__":
    sys.exit(main())
